/* Static, read-only replay. Decisions and receipts are generated by the Python engine. */
(function () {
  'use strict';

  function isObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function paragraphs(value) {
    return Array.isArray(value) && value.length > 0 && value.every(
      item => typeof item === 'string' && item.length > 0
    );
  }

  function validateResult(result, name) {
    if (!isObject(result) || !isObject(result.decision) ||
        !['ABSTAIN', 'AUTO_REPAIR', 'NO_CHANGE'].includes(result.decision.action)) {
      throw new Error(`invalid gate action in ${name}`);
    }
    if (!isObject(result.receipt) || !/^[0-9a-f]{64}$/.test(result.receipt.receipt_sha256 || '')) {
      throw new Error(`missing or invalid receipt in ${name}`);
    }
    if (result.decision.action === 'ABSTAIN' && result.selected_paragraphs != null) {
      throw new Error(`abstaining ${name} cannot select output`);
    }
    if (result.decision.action === 'AUTO_REPAIR' && !paragraphs(result.selected_paragraphs)) {
      throw new Error(`repairing ${name} requires selected output`);
    }
  }

  function validateBundle(value) {
    if (!isObject(value) || value.schema_version !== 'biosure.judge-replay/1.0' ||
        !Array.isArray(value.scenarios) || value.scenarios.length < 1) {
      throw new Error('invalid judge replay bundle');
    }
    const ids = new Set();
    for (const scenario of value.scenarios) {
      if (!isObject(scenario) || typeof scenario.id !== 'string' || ids.has(scenario.id) ||
          typeof scenario.label !== 'string' || !['public-excerpt', 'fictional'].includes(scenario.kind) ||
          !isObject(scenario.source) || !isObject(scenario.input) ||
          !paragraphs(scenario.input.reference_paragraphs) ||
          !paragraphs(scenario.input.observed_paragraphs) ||
          !paragraphs(scenario.proposed_paragraphs) ||
          !isObject(scenario.learned) ||
          !Array.isArray(scenario.workflow?.review_changes)) {
        throw new Error('invalid judge replay scenario');
      }
      if (scenario.kind === 'public-excerpt' &&
          (typeof scenario.source.article_url !== 'string' ||
           !scenario.source.article_url.startsWith('https://pmc.ncbi.nlm.nih.gov/articles/') ||
           scenario.source.license_uri !== 'https://creativecommons.org/licenses/by/4.0/')) {
        throw new Error('public source attribution is missing');
      }
      validateResult(scenario.workflow, 'workflow');
      validateResult(scenario.proposal, 'proposal');
      ids.add(scenario.id);
    }
    return value;
  }

  function deriveView(scenario) {
    return {
      id: scenario.id,
      label: scenario.label,
      isFictional: scenario.kind === 'fictional',
      sourceUnverified: true,
      articleUrl: scenario.source.article_url || null,
      source: scenario.source,
      referenceParagraphs: scenario.input.reference_paragraphs,
      observedParagraphs: scenario.input.observed_paragraphs,
      proposedParagraphs: scenario.proposed_paragraphs,
      changes: scenario.workflow.review_changes,
      learnedStatus: scenario.learned.proposal_status,
      learnedReason: scenario.learned.proposal_reason,
      learnedProposedParagraphs: scenario.learned.proposed_paragraphs,
      learnedProposalNote: scenario.learned.proposed_paragraphs == null
        ? `No model proposal: ${scenario.learned.proposal_reason}.` : null,
      gateAction: scenario.workflow.decision.action,
      gateReasons: scenario.workflow.decision.reason_codes,
      selectedParagraphs: scenario.workflow.selected_paragraphs,
      proposalAction: scenario.proposal.decision.action,
      proposalReasons: scenario.proposal.decision.reason_codes,
      proposalSelectedParagraphs: scenario.proposal.selected_paragraphs,
      receipt: scenario.proposal.proposal_receipt,
      gateReceipt: scenario.workflow.receipt,
    };
  }

  async function loadBundle(fetcher) {
    try {
      const response = await fetcher('./data.json', { cache: 'no-store' });
      if (!response.ok) throw new Error(`replay asset unavailable (HTTP ${response.status})`);
      return { ok: true, data: validateBundle(await response.json()) };
    } catch (error) {
      return { ok: false, error: `Could not load verified sample replay: ${error.message}` };
    }
  }

  function element(tag, className, value) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (value != null) node.textContent = String(value);
    return node;
  }

  function showParagraphs(target, values) {
    const list = element('ol', 'paragraphs');
    for (const value of values || []) list.append(element('li', '', value));
    target.replaceChildren(list);
  }

  function formatSpan(span) {
    const [start, end] = span;
    if (start === end) return start === 0 ? 'gap before paragraph 1' : `gap after paragraph ${start}`;
    return end === start + 1 ? `paragraph ${start + 1}` : `paragraphs ${start + 1}–${end}`;
  }

  function showChanges(target, changes) {
    if (!changes.length) {
      target.textContent = 'No changed paragraph position.';
      return;
    }
    const list = element('ul', 'change-list');
    for (const change of changes) {
      const ref = formatSpan(change.reference_span);
      const obs = formatSpan(change.observed_span);
      list.append(element('li', '', `${change.kind}: reference ${ref}, observed ${obs}`));
    }
    target.replaceChildren(list);
  }

  function renderScenario(scenario) {
    const view = deriveView(scenario);
    document.getElementById('results').hidden = false;
    document.getElementById('scenario-label').textContent = view.label;
    document.getElementById('source-type').textContent = view.isFictional
      ? 'FICTIONAL CONTROL — not external validation'
      : 'PUBLIC CC BY 4.0 EXCERPT — PDF text versus same-article JATS';
    const sourceLink = document.getElementById('article-link');
    sourceLink.hidden = !view.articleUrl;
    if (view.articleUrl) sourceLink.href = view.articleUrl;
    else sourceLink.removeAttribute('href');
    showParagraphs(document.getElementById('observed'), view.observedParagraphs);
    showParagraphs(document.getElementById('reference'), view.referenceParagraphs);
    showChanges(document.getElementById('changes'), view.changes);
    document.getElementById('learned-status').textContent =
      `${view.learnedStatus} · ${view.learnedReason}. Model ranks correspondence; it does not verify source truth.`;
    const learnedTarget = document.getElementById('learned-proposal');
    if (view.learnedProposedParagraphs) showParagraphs(learnedTarget, view.learnedProposedParagraphs);
    else learnedTarget.textContent = view.learnedProposalNote;
    showParagraphs(document.getElementById('submitted-proposal'), view.proposedParagraphs);
    document.getElementById('workflow-action').textContent =
      `${view.gateAction} · ${view.gateReasons.join(', ') || 'no reason code'}`;
    document.getElementById('proposal-action').textContent =
      `${view.proposalAction} · ${view.proposalReasons.join(', ') || 'no reason code'}`;
    const selected = document.getElementById('selected');
    if (view.proposalSelectedParagraphs) showParagraphs(selected, view.proposalSelectedParagraphs);
    else selected.textContent = 'No proposed text applied. Manual source review required.';
    document.getElementById('receipt').textContent = JSON.stringify({
      gate_receipt: view.gateReceipt,
      proposal_receipt: view.receipt,
    }, null, 2);
    document.getElementById('result-status').textContent =
      `${view.sourceUnverified ? 'SOURCE UNVERIFIED' : ''} · Static replay of Python engine output; not a live document check.`;
  }

  async function init() {
    const select = document.getElementById('scenario');
    const run = document.getElementById('run-audit');
    const status = document.getElementById('load-status');
    if (!select || !run || !status) return;
    run.disabled = true;
    const outcome = await loadBundle(window.fetch.bind(window));
    if (!outcome.ok) {
      status.textContent = outcome.error;
      status.className = 'status error';
      return;
    }
    for (const scenario of outcome.data.scenarios) {
      const option = element('option', '', scenario.label);
      option.value = scenario.id;
      select.append(option);
    }
    run.disabled = false;
    status.textContent = 'Sample replay loaded. Choose a scenario, then run the audit.';
    run.addEventListener('click', () => {
      const scenario = outcome.data.scenarios.find(item => item.id === select.value);
      if (!scenario) return;
      renderScenario(scenario);
      document.getElementById('results').scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { validateBundle, deriveView, loadBundle, formatSpan };
  }
  if (typeof document !== 'undefined') document.addEventListener('DOMContentLoaded', init);
})();
